package com.library.service; import com.library.dao.UserDAO; import com.library.enums.Role; import com.library.exception.AuthorizationException; import com.library.model.Member; import com.library.security.PasswordUtil; import com.library.session.SessionManager; import com.library.util.ValidationUtil; import java.time.LocalDate; import java.util.*;
public class MemberService { private final UserDAO dao=new UserDAO(); private void admin(){if(!SessionManager.hasRole(Role.ADMIN))throw new AuthorizationException("Admin access required.");} public List<Member> search(String term){admin();return dao.findMembers(term==null?"":term.trim());} public List<Member> activeMembers(){admin();return dao.findMembers("").stream().filter(m->"ACTIVE".equals(m.getStatus())).toList();} public Member get(long id){admin();return dao.findMember(id);} public void add(Member m,String password){admin();validate(m);ValidationUtil.password(password);m.setPasswordHash(PasswordUtil.hash(password));m.setRegistrationDate(LocalDate.now());dao.insertMember(m);} public void update(Member m){admin();validate(m);dao.updateMember(m);} public void resetPassword(long memberId,String password){admin();ValidationUtil.password(password);Member m=dao.findMember(memberId);if(m==null)throw new IllegalArgumentException("Student not found.");dao.updatePassword(m.getUserId(),PasswordUtil.hash(password));} public void deactivate(long id){admin();dao.setMemberStatus(id,"INACTIVE");} private void validate(Member m){ValidationUtil.enrollment(m.getMemberId());ValidationUtil.required(m.getName(),"Name");ValidationUtil.studentEmail(m.getEmail());ValidationUtil.phone(m.getPhone());ValidationUtil.required(m.getCourse(),"Course");ValidationUtil.required(m.getDepartment(),"Department");ValidationUtil.semester(m.getSemester());} }
